#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using LivingTable.Chess;
namespace LivingTable.Editor {
 public static class IntegratedFlowTests {
  static int count;static double deadline;
  static void Check(bool value,string name){count++;if(!value)throw new Exception("INTEGRATED FLOW: "+name);}
  public static void Run(){SessionState.SetString("IntegratedRoot",Path.GetFullPath("Logs/integrated-"+Guid.NewGuid().ToString("N")));EditorSceneManager.OpenScene(ChessContestRelease.DesktopScene);SessionState.SetBool("IntegratedFlow",true);EditorApplication.EnterPlaymode();}
  [InitializeOnLoadMethod]static void Resume(){if(!SessionState.GetBool("IntegratedFlow",false))return;GameSessionStore.TestRoot=SessionState.GetString("IntegratedRoot","");deadline=EditorApplication.timeSinceStartup+120;EditorApplication.update+=Tick;}
  static void Tick(){try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Timeout");if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;var t=UnityEngine.Object.FindFirstObjectByType<ChessTable>();if(t?.Vision==null)return;
   Camera.main.transform.SetPositionAndRotation(new Vector3(0,1.4f,-.4f),Quaternion.Euler(55,0,0));t.ChooseNewGame();Check(t.EntryPhase==1&&!t.Playing,"New game opens positioning stage");var names=t.GetComponentsInChildren<TableButtonVisual>().Select(b=>b.name).ToArray();Check(names.Length==2&&names.Contains("CONTINUE button")&&names.Contains("Menu button"),"Only Continue and Menu at entry");Check(t.GetComponentsInChildren<Transform>().Count(x=>x.name=="Polished burl oak knob")==4,"Four wooden adjustment knobs");Check(UnityEngine.Object.FindObjectsByType<TableFacingPanel>(FindObjectsSortMode.None).Any(p=>p.FixedToBoard),"Back panel fixed beyond board");
   t.ContinueEntry();Check(t.EntryPhase==2&&t.SelectingCorners,"Continue requests corners");t.AlignEntry();Check(t.EntryPhase==2&&!t.Aligned,"Cannot align incomplete markers");var surfaceCenter=new Vector3(.17f,.73f,.12f);var surfaceRotation=Quaternion.Euler(7,18,-4);var pts=new[]{new Vector3(-.28f,0,-.28f),new Vector3(.28f,0,-.28f),new Vector3(.28f,0,.28f),new Vector3(-.28f,0,.28f)}.Select(p=>surfaceCenter+surfaceRotation*p).ToArray();foreach(var p in pts)Check(t.SelectBoardCorner(p),"Corner placed");Check(t.GetComponentsInChildren<Transform>().Count(x=>x.name=="Square corner marker")==4,"Square markers");Check(t.GetComponentsInChildren<MeshFilter>().Count(x=>x.name=="Playable corner triangular edge"&&x.sharedMesh!=null)==4,"Triangular playable-edge indicators survive drawing pieces");Check(ChessTable.ViewAlignedOverBoard(surfaceCenter+surfaceRotation*Vector3.up*.7f,surfaceRotation*Vector3.down,surfaceCenter,surfaceRotation*Vector3.up),"Centered overhead view accepted");Check(!ChessTable.ViewAlignedOverBoard(surfaceCenter+new Vector3(.3f,.7f,0),Vector3.down,surfaceCenter,Vector3.up),"Off-axis view stays blue");Check(t.GetComponentsInChildren<Transform>().Any(x=>x.name=="Center plus horizontal 0"&&Mathf.Abs(x.localScale.x-.105f)<.0001f),"Plus guides enlarged three times");Check(t.GetComponentsInChildren<Transform>().Count(x=>x.name=="Corner edge axis")==8,"Two long edge axes per corner");Check(ChessTable.CornerLayoutState(pts,4)==1,"XYZ square geometry valid");var bad=(Vector3[])pts.Clone();bad[2]+=Vector3.up*.08f;Check(ChessTable.CornerLayoutState(bad,4)==-1,"Raised misaligned corner rejected red");Check(t.GetComponentsInChildren<Renderer>().Where(r=>r.name=="Square corner marker").All(r=>r.sharedMaterial.GetFloat("_Opacity")<.5f&&r.sharedMaterial.color.g>.9f),"Valid markers green and transparent");t.AlignEntry();Check(Vector3.Distance(t.transform.position,surfaceCenter)<.0001f&&Quaternion.Angle(t.transform.rotation,surfaceRotation)<.01f,"Four pinches retain XYZ and surface tilt");Check(Mathf.Abs(t.SquareLocal(4).y)<.00001f,"Physical piece base flush with pinch plane");var locked=t.transform.position;var lockedRotation=t.transform.rotation;foreach(float height in new[]{1.8f,1.1f}){Camera.main.transform.position=new Vector3(.1f,height,-.4f);UnityEngine.Object.FindFirstObjectByType<LivingTableExperience>().SendMessage("Update");t.SendMessage("Update");Check(Vector3.Distance(t.transform.position,locked)<.00001f&&Quaternion.Angle(t.transform.rotation,lockedRotation)<.001f,"Standing/sitting leaves world pose unchanged");}
   var plane=new ChessSurfaceSolver.Estimate{valid=true,center=surfaceCenter,rotation=surfaceRotation,size=.56f};var raised=plane;raised.center+=surfaceRotation*Vector3.up*.05f;var constrained=ChessTable.ConstrainSnapToPinchPlane(raised,plane);Check(Vector3.Distance(constrained.center,surfaceCenter)<.00001f,"Camera fit cannot lift user plane");Check(Vector3.Distance(t.CaptureSession().registration.center,surfaceCenter)<.0001f,"World registration records calibrated surface");
   Check(t.EntryPhase==4&&t.SizingKing&&t.BoardPoseLocked,"Align locks geometry and opens king sizing without scan");Check(t.GetComponentsInChildren<TableButtonVisual>().Any(b=>b.name=="PLAY button"),"Play available directly during sizing");Check(t.VisiblePieceCount==1,"King sizing guide visible after alignment");Check(!t.Vision.Checking,"No scan requested after alignment");t.SendMessage("CompleteKingSizing");Check(t.Playing&&t.Match.Position.Side==1&&!t.Recovering,"Sizing Play starts White without setup scan gate");Check(t.GetComponentsInChildren<ChessPhysicalPieceTag>().Length==32,"Every virtual piece has persistent identity tag");
   Check(t.AcceptObservedBaseline(t.Version),"Verified initial board enables play");var reg=t.CaptureSession().pieceRegistry;t.HoverPiece(t.SquareWorld(12)+t.transform.up*.035f);Check(t.HoveredPieceSquare==12,"Hover covers physical piece square");Check(t.ConfirmedPlacementSquare==-1,"No purple confirmation before verified move");string pawnId=reg.At(12).id;var patch=new Color32[144];for(int i=0;i<144;i++){byte v=(byte)(i%12>3&&i%12<8&&i/12>2?220:35);patch[i]=new Color32(v,v,v,255);}var shape=ChessPieceRegistry.Describe(patch);Check(shape!=null&&shape.Length==288,"Shape descriptor includes normalized appearance and edges");var shapes=Enumerable.Range(0,64).Select(i=>shape).ToArray();t.LearnPhysicalPieces(shapes,Vector3.up);var move=t.Match.Position.LegalMoves().Single(m=>m.From==12&&m.To==28);string key=t.Match.Position.Key();Check(t.PreviewTrackedMove(move,t.Version,shape,Vector3.up),"Local profile creates visual preview");Check(t.Match.Position.Key()==key&&t.VisualMovePreview&&!t.AwaitingMoveAcceptance,"Local preview cannot commit or require accept button");Check(t.GetComponentsInChildren<ChessPhysicalPieceTag>().Any(tag=>tag.PieceId==pawnId&&Vector3.Distance(tag.transform.position,t.SquareWorld(28))<.001f),"Physical identity follows preview");t.CancelHumanReview();Check(t.Match.Position.Key()==key&&!t.VisualMovePreview,"Rejected preview restores authoritative state");Check(t.CommitObservedMove(move,t.Version,true,true),"Backend approved move commits automatically");Check(t.ConfirmedPlacementSquare==28,"Verified destination receives purple glow");Check(t.CaptureSession().pieceRegistry.At(28).id==pawnId,"Identity survives committed move");var restored=JsonUtility.FromJson<ChessTable.SessionState>(JsonUtility.ToJson(t.CaptureSession()));Check(restored.pieceRegistry.At(28).id==pawnId,"Identity and profile persist in save");Check(!reg.Recognizes(28,shape,Vector3.forward),"Different viewing direction cannot claim shape match");
   t.SetPieceOpacity(0);Check(t.PieceOpacity==0,"Opacity reaches invisible");t.SetPieceOpacity(1);Check(t.PieceOpacity==1,"Opacity reaches opaque");t.SetPieceOpacity(.35f);Check(ChessTable.NearestColor(ChessPosition.Initial().Board)==1&&ChessTable.NearestColor(ChessPosition.Initial().Board.Reverse().ToArray())==-1,"Closest side inferred in both orientations");Check(LivingTableExperience.PiecePinchActive(.0254f,false)&&LivingTableExperience.PiecePinchActive(.06f,false),"Grip accepts one inch and wider");Check(!LivingTableExperience.PiecePinchActive(.095f,true),"Wide opening releases grip");
   var fixture=ChessPosition.FromFen("4k3/8/8/3p4/4P3/8/8/4K3 w - - 0 1");var registry=new ChessPieceRegistry();registry.Enroll(fixture);var taken=registry.At(35).id;var capture=fixture.LegalMoves().Single(m=>m.From==28&&m.To==35);registry.Advance(fixture,capture);Check(registry.pieces.Single(p=>p.id==taken).captured&&registry.At(35).kind==1,"Capture keeps victim identity and moves attacker");
   string continuedKey=t.Match.Position.Key();t.BeginEntry();t.ContinueEntry();foreach(var local in new[]{new Vector3(-.28f,0,-.28f),new Vector3(.28f,0,-.28f),new Vector3(.28f,0,.28f),new Vector3(-.28f,0,.28f)})t.SelectBoardCorner(t.transform.TransformPoint(local));t.AlignEntry();Check(t.SizingKing&&!t.Vision.Checking,"Continued game sizes before scanning");t.SendMessage("CompleteKingSizing");Check(t.Match.Position.Key()==continuedKey&&t.Match.Position.Side==-1,"Play preserves continued Black turn and all positions");
   t.QuickPlay();t.ContinueEntry();foreach(var local in new[]{new Vector3(-.28f,0,-.28f),new Vector3(.28f,0,-.28f),new Vector3(.28f,0,.28f),new Vector3(-.28f,0,.28f)})t.SelectBoardCorner(t.transform.TransformPoint(local));t.AlignEntry();Check(t.SizingKing&&t.VisiblePieceCount==1&&!t.Vision.Checking,"Quick Play goes straight to visible king sizing");t.SendMessage("CompleteKingSizing");Check(t.Playing&&t.Match.Position.Side==1&&!t.Recovering&&!t.Vision.Checking,"Quick Play starts standard chess with no setup scan");
   t.NewGame();Finish(0,"INTEGRATED_FLOW_TESTS_PASSED "+count);
  }catch(Exception e){Finish(1,e.ToString());}}
  static void Finish(int code,string message){SessionState.SetBool("IntegratedFlow",false);EditorApplication.update-=Tick;if(code==0){File.WriteAllText("Builds/Integrated-flow-tests.txt",count+" integrated scene/model checks passed; physical recognition, tray fit and interaction comfort require headset acceptance.");Debug.Log(message);}else Debug.LogError(message);EditorApplication.Exit(code);}
 }
}
#endif
